{
  "positionId": "P04",
  "interviews": [
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "하중과 조립 상대 부품을 고려해 주요 치수를 정할 수 있는지 평가한다. 감속기 축 지름을 선택한 근거가 주어진 하중 조건과 베어링에 맞는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "기계요소설계 수업의 감속기 축 설계 계산 과제에서 교재에 주어진 하중 조건을 사용했다.",
          "task": "축 지름과 베어링을 선정하고 손도면과 계산서를 제출하는 개인 과제였다.",
          "action": "축 지름을 선택한 근거를 하중이 전달되는 위치와 방향, 계산 내용, 베어링과 맞물리는 치수 중 실제로 고려한 정보로 설명한다.",
          "result": "제출한 계산서나 손도면의 축 지름이 설명한 근거와 어떻게 연결되는지 설명한다."
        },
        "expectedEvidence": [
          "축 지름을 선택한 구체적인 근거",
          "선택의 근거로 사용한 하중 조건이나 계산 내용",
          "선정한 베어링과 축 지름의 관계"
        ]
      },
      "question": "기계요소설계 수업의 감속기 축 설계 계산 과제에서 축 지름을 정하셨을 때, 그 지름을 선택한 근거는 무엇이었나요?",
      "answerTip": "한 가지 사례를 중심으로 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "축 지름을 선택한 근거를 과제에서 사용한 하중 조건이나 계산 내용과 연결해 구체적으로 설명한다.",
            "하중이 축에 전달되는 방식과 선정한 베어링의 치수 관계를 들어 선택한 지름이 적절한 이유를 일관되게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "강도나 베어링 치수 등을 축 지름 선택의 근거로 제시하지만 실제 하중 조건이나 계산 내용은 구체적이지 않다.",
            "선택한 지름과 하중 또는 베어링의 관계를 설명하지만 일부 연결이 빠져 있다."
          ]
        },
        "poor": {
          "criteria": [
            "축 지름을 선택한 근거를 제시하지 못하거나 과제 수행 소감만 이야기한다.",
            "계산값이나 교재를 따랐다고만 답해 하중 조건 또는 베어링과 선택한 지름의 관계를 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "3D 모델을 양산 도면으로 정리할 때 기능에 필요한 치수만 좁은 공차로 지정할 수 있는지 평가한다. 치수 공차를 좁힐 대상을 고르는 기준에 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "입사 후 기계 부품의 3D 모델을 양산용 2D 도면으로 옮기는 상황이다.",
          "task": "도면에서 치수 공차를 좁힐 대상을 고른다.",
          "action": "치수 편차가 부품의 기능과 조립 상대 부품에 미치는 영향을 기준으로 공차를 좁힐 치수를 구분한다.",
          "result": "선택한 기준으로 기능과 조립에 필요한 치수를 관리하면서 불필요하게 엄격한 가공 요구를 줄일 수 있음을 설명한다."
        },
        "expectedEvidence": [
          "치수 공차를 좁힐 치수를 고르는 기준",
          "그 기준을 뒷받침하는 기능이나 끼워맞춤의 구체적인 예",
          "공차를 좁혀야 하는 치수와 그렇지 않은 치수를 구분하는 이유"
        ]
      },
      "question": "입사 후 기계 부품의 3D 모델을 양산용 2D 도면으로 옮긴다면, 치수 공차를 좁힐 치수를 고르는 기준은 무엇인가요?",
      "answerTip": "답변의 요점을 먼저 짧게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "치수 편차가 기능이나 조립에 미치는 영향을 공차 선택 기준으로 제시하고 구체적인 치수 또는 끼워맞춤 사례로 설명한다.",
            "같은 기준으로 공차를 좁혀야 하는 치수와 일반 공차로 충분한 치수를 구분해 불필요한 가공 요구를 피하는 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "기능이나 조립에 중요한 치수의 공차를 좁힌다는 기준을 제시하지만 구체적인 예가 부족하다.",
            "공차를 좁혀야 하는 이유는 설명하지만 일반 공차로 충분한 치수와 구분하는 근거는 일부 빠져 있다."
          ]
        },
        "poor": {
          "criteria": [
            "치수 공차를 좁힐 대상을 고르는 기준을 제시하지 못하거나 도면 작성 도구의 사용법만 설명한다.",
            "기능이나 조립에 미치는 영향과 관계없이 모든 치수의 공차를 좁혀야 한다고 답한다."
          ]
        }
      }
    }
  ]
}

